const meds=[
['Norepinephrine','Vasopressor','First-line vasopressor in distributive shock. Predominantly alpha effect; titrate per ordered MAP target.','MAP, rhythm, perfusion, lactate, urine output','Extravasation; rising dose warrants reassessment of source control, volume status, cardiac function, acidemia.'],
['Vasopressin','Vasopressor','Non-catecholamine adjunct commonly used in vasodilatory shock. Often ordered at a fixed dose.','MAP, perfusion, sodium, ischemic signs','Follow local protocol for dose and central/peripheral administration.'],
['Epinephrine','Vasopressor / inotrope','Increases inotropy, chronotropy, and vasoconstriction; used for refractory shock, anaphylaxis, and ACLS.','MAP, rhythm, lactate, glucose, potassium','Can raise lactate through beta-adrenergic effect; interpret clinical context.'],
['Phenylephrine','Vasopressor','Predominantly alpha agonist; increases SVR with minimal direct beta effect.','MAP, HR, perfusion','May reduce stroke volume in some patients; evaluate cause of hypotension.'],
['Dobutamine','Inotrope','Beta-agonist inotrope for low cardiac output states when blood pressure allows.','HR/rhythm, BP, perfusion, urine output','Can cause hypotension and tachyarrhythmias.'],
['Amiodarone','Antiarrhythmic','Used for ventricular arrhythmias and selected atrial tachyarrhythmias per order.','Rhythm, QTc, BP, liver function','IV administration can cause hypotension; verify line/filter and compatibility policy.'],
['Diltiazem','Rate control','Calcium channel blocker for selected supraventricular tachyarrhythmias.','HR, BP, rhythm','Use caution with hypotension or reduced systolic function; follow provider order.'],
['Propofol','Sedative','Short-acting sedative commonly used for mechanically ventilated patients.','RASS, BP, triglycerides, calories, respiratory status','Hypotension and hypertriglyceridemia; track lipid calories and local monitoring practice.'],
['Dexmedetomidine','Sedative','Alpha-2 sedative; may support lighter, arousable sedation.','RASS, HR, BP','Bradycardia and hypotension are common concerns.'],
['Fentanyl','Analgesic','Opioid analgesia for pain and ventilator synchrony as ordered.','Pain scale, RR, BP, bowel function','Accumulation/withdrawal considerations; assess sedation separately when possible.'],
['Midazolam','Sedative','Benzodiazepine sedation for selected patients, seizures, or procedures.','RASS, respiratory status, BP','May accumulate, especially with prolonged infusion or organ dysfunction.'],
['Ketamine','Analgesic / sedative','Dissociative agent used for procedures, induction, or adjunct analgesia/sedation.','BP, HR, mental status, secretions','Can increase secretions; emergence reactions possible.'],
['Heparin','Anticoagulant','Anticoagulation infusion or prophylaxis per indication and protocol.','aPTT/anti-Xa, platelets, bleeding signs','Use institution nomogram; consider HIT when platelets fall in the appropriate context.'],
['Insulin','Metabolic','IV infusion for hyperglycemia, DKA/HHS, or hyperkalemia per protocol.','Glucose frequency, potassium, anion gap when applicable','Never pause monitoring; hypoglycemia and hypokalemia are major risks.'],
['Sodium bicarbonate','Buffer','May be used in specific severe acid-base or toxicologic scenarios; treats numbers less than underlying cause.','pH/PaCO2, sodium, potassium, calcium, volume status','Produces CO2; adequate ventilation matters. Verify indication and local practice.']];
const dx=[
['Septic shock','Shock','Suspected infection with vasodilation and impaired perfusion.','MAP, lactate trend, UOP, mentation, cultures, antibiotic timing','Think source control, volume status, cardiac function, and peripheral perfusion—not MAP alone.'],
['Cardiogenic shock','Shock','Low cardiac output causing tissue hypoperfusion, often with congestion.','MAP, rhythm, UOP, lactate, extremities, lung exam','Watch carefully for pulmonary edema and dysrhythmia; hemodynamic plan is individualized.'],
['Hypovolemic shock','Shock','Inadequate circulating volume from hemorrhage or fluid loss.','HR, MAP, Hgb/bleeding, UOP, mentation','Find and control the loss; reassess response to ordered resuscitation.'],
['Obstructive shock','Shock','Mechanical impairment of cardiac filling or output (e.g., PE, tamponade, tension physiology).','Sudden change, JVD, lung sounds, bedside ultrasound if available','Escalate early; definitive treatment is cause-specific.'],
['ARDS','Respiratory','Inflammatory noncardiogenic pulmonary edema with impaired oxygenation.','SpO2/ABG, P/F ratio, plateau pressure, ventilator synchrony','Lung-protective ventilation and proning decisions are team/protocol driven.'],
['COPD exacerbation','Respiratory','Airflow obstruction with dynamic hyperinflation risk.','Work of breathing, ABG, auto-PEEP, mental status','Allow adequate exhalation; rising pressures can be air trapping.'],
['Pulmonary edema','Respiratory','Fluid in alveoli from cardiogenic or noncardiogenic causes.','Oxygenation, work of breathing, BP, I&O, lung exam','Rapid changes require re-evaluation of cause and ventilation plan.'],
['Pulmonary embolism','Respiratory','Pulmonary vascular obstruction that can strain the right ventricle.','O2 need, HR, BP, signs of RV strain, bleeding risk','Sudden hypotension or syncope signals high risk—escalate promptly.'],
['Acute kidney injury','Renal','Abrupt decline in renal function from perfusion, injury, or obstruction.','UOP, creatinine, potassium, bicarbonate, volume status','Trend rather than a single creatinine; review nephrotoxins and obstruction clues.'],
['DKA / HHS','Endocrine','Hyperglycemic crisis with dehydration; DKA includes ketoacidosis.','Glucose, potassium, anion gap, bicarbonate, neuro status','Use institutional insulin/fluid/electrolyte protocol; potassium drives safety.'],
['GI bleeding','Hematology','Overt or occult blood loss from GI tract.','Hemodynamics, Hgb trend, stool/emesis, coags, access','Massive bleeding is a resuscitation and source-control problem; follow transfusion policy.'],
['DIC','Hematology','Consumptive coagulopathy secondary to an underlying trigger.','Platelets, fibrinogen, PT/INR, bleeding/thrombosis','Treat the trigger; component support follows provider/institutional plan.'],
['Status epilepticus','Neuro','Prolonged or recurrent seizure activity without recovery.','Airway, glucose, temperature, seizure timing, EEG if ordered','Time and document events precisely; airway and medication sequence are protocol-driven.'],
['Increased ICP','Neuro','Elevated intracranial pressure risks reduced cerebral perfusion.','Neuro checks, pupils, BP/MAP, sodium/osmolality if ordered','Avoid delays in new neuro changes; positioning and osmotherapy follow local orders.'],
['Post-cardiac arrest syndrome','Cardiac','Global ischemia-reperfusion injury after ROSC.','Airway/O2/CO2, MAP, rhythm, temperature, glucose, neuro exam','Avoid hyperoxia/hypotension; follow your post-ROSC pathway.']];
const quick=[
['MAP <65 / refractory hypotension','Confirm measurement and rhythm; assess perfusion, volume status, bleeding, sepsis/source control, pump failure, obstruction, and medication effects. Trend lactate/UOP/mentation; escalate early.','Call/escalate for worsening perfusion, rapidly increasing pressor needs, new dysrhythmia, suspected hemorrhage, or concern for obstruction.'],
['Severe metabolic acidosis','Confirm ABG/VBG and chemistry; calculate anion gap; assess lactate, ketones, renal failure, toxins, diarrhea/renal losses. Assess ventilation—bicarbonate can increase CO2 burden.','Escalate severe acidemia, rising lactate, hyperkalemia, declining mental status, or ventilation failure.'],
['Refractory hypoxemia','Check patient first: airway, chest rise, waveform, secretions, tube depth, breath sounds, hemodynamics. Then circuit/ventilator: FiO2 source, disconnection, pressures, PEEP, alarms. Consider edema, ARDS, PE, pneumothorax.','Call immediately for rapidly falling SpO2, unilateral absent sounds, severe distress, instability, or suspected tension physiology.'],
['Post-ROSC','Prioritize airway/ventilation, avoid hypoxemia and hyperoxia, support ordered MAP target, obtain 12-lead/labs, temperature management, and frequent neurologic assessment.','Activate your facility post-arrest pathway; document timing and interventions.'],
['Sudden ventilator deterioration','Use DOPE: Displacement, Obstruction, Pneumothorax, Equipment. Disconnect and bag per emergency protocol if indicated; assess patient and call for help.','A sudden pressure, volume, or oxygenation change is an emergency until assessed.']];
// Batch 2: educational summaries only. Follow current orders, pump library, pharmacy, and local policy.
const enrich=(name,detail,source)=>{let x=meds.find(x=>x[0]===name);if(x){x[5]=detail;x[6]=source}};
enrich('Ketamine','Common examples: RSI 1-2 mg/kg IV; analgesia 0.1-0.3 mg/kg IV slowly or 0.1-0.4 mg/kg/hr. ICU-sedation range is protocol-dependent. Titrate to ordered pain/RASS and reassess BP, HR, respiratory status, SpO2, ETCO2 when available, secretions, and mental status. Stop/escalate for apnea, respiratory depression, severe hypertension/tachyarrhythmia, laryngospasm, or unsafe airway.','DailyMed ketamine label; multi-society consensus');
enrich('Heparin','Common VTE example: 80 units/kg IV bolus then 18 units/kg/hr; lower-intensity starts are indication-specific. A common concentration is 25,000 units/250 mL (100 units/mL). Titrate only with the active anti-Xa/aPTT nomogram. Stop/notify for active bleeding, critical result, suspected HIT, new thrombosis, or major platelet fall.','UW Medicine protocols; practical heparin guidance');
enrich('Amiodarone','For recurrent VF/unstable VT: 150 mg in 100 mL D5W over 10 min, then 1 mg/min for 6 hr, then 0.5 mg/min. AF with RVR needs indication-specific orders. Use continuous ECG/BP, track QTc and K/Mg, and slow/stop for hypotension, bradycardia, AV block, QT prolongation, or site injury.','DailyMed amiodarone IV label');
meds.push(
['Rocuronium / succinylcholine','RSI paralysis','Neuromuscular blockade for RSI; neither provides analgesia, amnesia, or sedation.','Induction before paralysis, airway/ventilation readiness, post-intubation analgesia/sedation, TOF if ongoing blockade','Confirm unconsciousness and immediate oxygenation/ventilation capability before administration.','Rocuronium RSI: 0.6-1.2 mg/kg IV. Succinylcholine adult label average: 0.6 mg/kg IV; local RSI protocols vary. Single RSI doses are not titrated. Avoid succinylcholine after acute burns, crush trauma, denervation, upper motor-neuron injury, or myopathy because of hyperkalemia risk; assess malignant-hyperthermia, bradycardia, and prolonged-apnea risk.','DailyMed rocuronium and succinylcholine labels'],
['Nicardipine','Antihypertensive infusion','Short-term severe hypertension control when oral therapy is not feasible; syndrome-specific targets apply.','Continuous BP/HR, ordered SBP/MAP goal, perfusion, infusion site','Avoid precipitous BP reduction; stop for unacceptable hypotension/tachycardia.','Label: start 5 mg/hr; increase 2.5 mg/hr every 5 min (rapid) or 15 min (gradual); max 15 mg/hr. Common premixes are 0.1 or 0.2 mg/mL. Contraindicated in advanced aortic stenosis. Watch for hypotension, reflex tachycardia, angina/HF worsening, and site injury.','DailyMed Cardene IV label'],
['Nitroglycerin','Vasodilator infusion','Acute coronary ischemia, cardiogenic pulmonary edema, and selected hypertensive emergencies when preload/BP permit.','Continuous BP/HR, chest pain, work of breathing, pulmonary edema, hemodynamics','Stop/escalate for hypotension, syncope, worsening ischemia, or marked rate change.','Label: start 5 mcg/min with non-adsorptive tubing; increase 5 mcg/min every 3-5 min initially. Common premix: 50 mg/250 mL (200 mcg/mL). Avoid preload-dependent states and recent PDE-5 inhibitor or riociguat exposure. Confirm tubing/filter policy.','DailyMed nitroglycerin IV label'],
['Furosemide infusion','Loop diuretic infusion','Controlled diuresis for acute pulmonary edema/volume overload; regimen is protocol-dependent.','Strict I/O, urine output, weight, BP, creatinine/BUN, Na/K/Mg/bicarbonate, hearing symptoms','Stop/escalate for severe hypotension, worsening oliguria/azotemia, electrolyte loss, or hearing change.','A common adult approach is a loading dose then 5-20 mg/hr, individualized for renal function and prior exposure. A common concentration is 1 mg/mL. Titrate to ordered urine-output/net-balance goal. Contraindicated in anuria; adult IV infusion should not exceed 4 mg/min.','DailyMed furosemide injection label'],
['Magnesium sulfate','Electrolyte / antiarrhythmic','Hypomagnesemia replacement; torsades/polymorphic VT with prolonged QT.','Magnesium, potassium/calcium as indicated, renal function/UOP, ECG with unstable arrhythmia','Stop/escalate for hyporeflexia, respiratory decline, major hypotension/bradycardia, or conduction block.','For torsades with a pulse, a common emergency dose is 1-2 g IV diluted over about 5-15 min; repeat only per ACLS/local protocol. Replacement thresholds are protocol-dependent. Reduce repeated empiric dosing in renal impairment. Verify grams versus milligrams and concentration.','Electrolyte-replacement and EMS protocols']
);
dx.push(
['Hyperkalemia','Electrolyte emergency','Severe potassium elevation can cause lethal conduction disturbance even with an initially normal ECG.','Repeat potassium, rhythm/12-lead ECG, glucose after insulin, renal function, acid-base status','ECG changes, K >6.5, rapid rise, weakness, oligo-anuria, acidosis, or poor response require urgent escalation.','Immediate approach: cardiac monitoring, ECG, repeat potassium. IV calcium stabilizes myocardium with ECG changes/instability but does not lower K. Shift K with insulin/dextrose and albuterol per order; remove K with appropriate diuresis, binder, or dialysis. Recheck K and glucose for delayed hypoglycemia.','ACEP adult hyperkalemia algorithm'],
['Hyponatremia','Electrolyte emergency','Severity and onset matter: assess headache, nausea, confusion, seizures, coma, and respiratory compromise.','Frequent sodium and neurologic checks; glucose, osmolality, urine output, urine studies as ordered','Seizure, coma, deterioration, respiratory failure, acute water intoxication, or overcorrection require urgent escalation.','For severe symptoms, a common US regimen is 3% saline 100 mL IV over 10 min, repeat up to twice if symptoms persist; local order set controls. Initial goal is about 4-6 mmol/L rise, not normalization. Avoid correction >8 mmol/L/24 hr in high-risk patients.','US/European guideline comparison'],
['Hypertensive emergency','Cardiovascular emergency','Severe BP elevation plus acute target-organ injury; the BP number alone is not an emergency.','Confirmed BP technique, neuro/cardiac/renal/perfusion status, diagnosis-specific target','Suspected dissection, stroke/ICH, ACS/pulmonary edema, eclampsia, or catecholamine crisis needs syndrome-specific treatment.','Screen brain, arteries, retina, kidneys, and heart. Use a monitored, titratable IV agent appropriate to the syndrome. General guidance is no more than about 20-25% SBP/MAP reduction in the first hour, then toward roughly 160/100 over 2-6 hr if stable.','AHA acute-care BP scientific statement'],
['Alcohol withdrawal / CIWA-Ar','Withdrawal','CIWA-Ar is unreliable for intubated, deeply sedated, delirious, or noncommunicative patients.','Last drink, prior seizures/DTs, vitals, orientation, autonomic signs, glucose/electrolytes, airway/ventilation','Seizure, DTs, unsafe agitation, autonomic instability, hyperthermia, rising sedative need, or respiratory depression need escalation.','Use the local symptom-triggered/front-loading/fixed-dose pathway; benzodiazepines are first-line. If CIWA-Ar is invalid, use the ICU RASS/MINDS pathway. Give thiamine as ordered and correct fluids/electrolytes. Alpha-2 agonists/beta-blockers may mask signs and do not treat withdrawal.','ASAM alcohol withdrawal guideline'],
['Delirium / CAM-ICU','Neuro / ICU assessment','Assess arousal before CAM-ICU: RASS -4/-5 is coma and not assessable.','RASS, CAM-ICU trend, baseline cognition, oxygenation/ventilation, infection, glucose, medication review','New focal deficit, seizure, falling consciousness, severe gas-exchange issue, hypoglycemia, sepsis, or unsafe agitation needs evaluation.','CAM-ICU positive: acute/fluctuating course plus inattention, plus altered LOC or disorganized thinking. Treat the driver and apply ABCDEF: pain, SAT/SBT coordination, appropriate sedation, delirium checks, early mobility, and family engagement.','SCCM ICU Liberation Bundle'],
['ABG interpreter','Bedside tool','Use a consistent sequence: pH, primary process, expected compensation, anion gap/albumin, mixed disorder, clinical cause.','pH, PaCO2, HCO3, chemistry HCO3 when available, Na/Cl/albumin, lactate/ketones as indicated','Compensation outside expected range or high-gap mismatch suggests mixed disease.','Metabolic acidosis expected PaCO2 = 1.5 x HCO3 + 8 +/-2. Metabolic alkalosis expected PaCO2 about 0.7 x (HCO3-24)+40 +/-2. AG = Na-(Cl+HCO3); albumin-corrected AG about measured AG+2.5 x (4-albumin g/dL).','Merck Manual acid-base disorders'],
['Oxygen-delivery devices','Bedside tool','FiO2 is estimated unless a device delivers a fixed concentration; fit, minute ventilation, and equipment matter.','Ordered SpO2 target, work of breathing, RR, mental status, oxygenation, hypercapnia/acidosis','Rising O2 need, persistent hypoxemia, exhaustion, worsening hypercapnia/acidosis, or declining mental status requires early airway escalation.','Nasal cannula 1-6 L/min about 24-44%. Simple mask 6-10 L/min about 35-50%: never below 6. Nonrebreather 10-15 L/min about 60-80%: keep reservoir inflated. Venturi 24-60% adapter-specific. HFNC up to 60 L/min. CPAP one pressure; BiPAP IPAP/EPAP. NIV is unsafe/failing with inability to protect airway, vomiting, secretions, major instability, or no improvement.','Open RN oxygenation equipment']
);
const updateDx=(name,overview,monitor,pearl)=>{const x=dx.find(d=>d[0]===name);if(x){x[2]=overview;x[3]=monitor;x[4]=pearl;x.splice(5)}};
updateDx('Septic shock','Infection-driven circulatory/cellular dysfunction; vasodilation, leak, maldistributed flow, and septic cardiomyopathy can reduce perfusion despite an acceptable BP. Assess source, cultures, antibiotic timing, fluid history, mentation, skin/cap refill, UOP, lactate, and organ dysfunction.','Activate the sepsis pathway; obtain ordered cultures without delaying antimicrobials; give ordered antibiotics; assess fluid responsiveness; titrate ordered MAP goal; and trend perfusion, UOP, lactate, cap refill, oxygenation, glucose, and source control after every fluid/vasoactive change.','Escalating pressors, lactate, mottling, oliguria, mentation change, hypoxemia, arrhythmia, or uncontrolled source are red flags. MAP at goal does not prove adequate perfusion. Source: Surviving Sepsis Campaign 2021.');
updateDx('Cardiogenic shock','Inadequate forward flow from pump failure, ischemia, mechanical complication, or dysrhythmia. Assess hypotension/narrow pulse pressure, cool extremities, oliguria, lactate, edema/JVD, ischemia, rhythm, murmur, and ventricular function.','Escalate for rapid diagnostic clarification; obtain ordered ECG/labs/bedside echo; treat precipitant; support oxygenation/perfusion; titrate ordered vasoactive/inotropic support; track balance; and prepare for coronary/structural/MCS evaluation when indicated.','Pulmonary edema, recurrent ischemia, malignant rhythm, mechanical complication, rising lactate, falling UOP, or rising support are red flags. Wet and cold can coexist; fluid may worsen congestion without improving flow. Source: ESICM shock consensus.');
updateDx('Hypovolemic shock','Inadequate circulating volume from hemorrhage or fluid loss. Assess loss, tachycardia, narrowing pulse pressure, cool clammy skin, cap refill, flat neck veins, UOP, mentation, lactate, Hgb, and concealed bleeding.','Identify/control loss; activate hemorrhage/transfusion pathway when indicated; obtain access; give ordered blood/fluids; prevent hypothermia; and trend perfusion, UOP, lactate, Hgb, coags, calcium, and response.','Ongoing loss, transient response then decline, acidosis, coagulopathy, hypothermia, hypocalcemia, or rising pressor need are red flags. Normal BP does not exclude major loss. Source: Management of circulatory shock and hypotension.');
updateDx('Obstructive shock','Mechanical barrier to filling/ejection: massive PE, tamponade, or tension pneumothorax. Assess sudden hypotension, syncope, JVD, unilateral absent sounds, hypoxemia, RV strain, tamponade findings, or abrupt decline with positive pressure.','Call immediate provider/rapid response; support oxygenation/perfusion; obtain focused ultrasound/emergent diagnostics without delaying definitive treatment; prepare decompression, drainage, or PE reperfusion pathway; and reassess after each step.','Peri-arrest state, rising O2/pressor need, severe RV dysfunction, absent unilateral sounds, or tamponade signs are red flags. Pressors buy time; obstruction must be relieved. Source: RUSH assessment review.');
updateDx('ARDS','Diffuse inflammatory lung injury with noncardiogenic edema, shunt, low compliance, and oxygenation failure. Assess acute insult, bilateral opacities, P/F ratio, FiO2/PEEP need, compliance, ABGs, and dyssynchrony.','Use ordered lung-protective ventilation based on predicted body weight; trend plateau/driving pressures, P/F, gases, SpO2, compliance, and synchrony; coordinate proning, sedation, paralysis, fluid, and rescue pathway. Protect tubes/lines/skin during proning.','Refractory hypoxemia, rising plateau pressure, sudden compliance loss, barotrauma, acidosis, collapse, or unsafe dyssynchrony are red flags. Small tidal volume uses predicted body weight. Source: ATS ARDS update.');
updateDx('COPD exacerbation','Acute airway inflammation/bronchospasm/mucus with expiratory flow limitation and auto-PEEP risk. Assess dyspnea, wheeze, expiration, work, air movement, PaCO2/acidosis, fatigue, mentation, and mimics.','Titrate ordered oxygen target; give ordered bronchodilators/steroids/antibiotics; trend effort, mentation, gases, secretions, and response; use NIV when appropriate; allow adequate exhalation and monitor auto-PEEP if ventilated.','Acidosis, falling consciousness, exhaustion, refractory hypoxemia, secretion inability, instability, or NIV failure are red flags. Falling RR may mean fatigue, not improvement. Source: hospitalized COPD-exacerbation guidance.');
updateDx('Pulmonary edema','Interstitial/alveolar fluid from hydrostatic pressure, permeability, or both. Assess dyspnea, orthopnea, crackles, frothy sputum, hypoxemia, imaging, BP, JVD, edema, weight, and cause.','Support oxygenation/ventilation; sit upright when tolerated; prepare ordered CPAP/BiPAP; treat precipitant; give ordered diuretic/vasodilator; trend effort, SpO2/ABG, BP, UOP, balance, weight, renal function, and electrolytes.','Escalating O2 need, pink froth, severe hypertension/hypotension, ischemia, rhythm change, acidosis, exhaustion, or declining mentation are red flags. Wet lungs do not always mean whole-body volume overload. Source: ACC/AHA/HFSA and ESC HF comparison.');
updateDx('Pulmonary embolism','Pulmonary arterial obstruction increases RV afterload; RV dilation can reduce LV filling and cause obstructive shock. Assess sudden dyspnea/chest pain/tachycardia/hypoxemia/syncope, RV strain, bleeding risk, and VTE history.','Support oxygenation/perfusion; obtain ordered ECG, biomarkers, CT, and echo; initiate/monitor anticoagulation per protocol; use response-guided fluids; activate PERT/reperfusion pathway for high-risk deterioration; trend RV function, bleeding, platelets, and assays.','Hypotension, syncope, rising O2 need, severe RV dysfunction, lactate, mentation change, or arrest are red flags. Excess fluid can worsen RV dilation/septal shift. Source: AHA/ACC acute PE guideline.');
updateDx('Acute kidney injury','Abrupt filtration/homeostasis loss from perfusion injury, intrinsic injury, obstruction, or mixed causes; creatinine can lag. Assess UOP, creatinine trend, balance, K/acidosis, nephrotoxins, hemodynamics, pigment injury, and obstruction.','Measure UOP accurately; verify catheter patency; trend creatinine/BUN/K/bicarbonate/Mg/phosphate/weight/balance; optimize perfusion without overload; adjust nephrotoxins/renal drugs; investigate obstruction; prepare nephrology/RRT if indicated.','Refractory hyperkalemia/acidosis, pulmonary edema, uremia, rapidly worsening oliguria/anuria, or toxins are red flags. Stage with worst creatinine or UOP criterion. Source: KDIGO-based AKI review.');
updateDx('DKA / HHS','DKA is insulin deficiency with ketosis/acidosis; HHS is profound hyperglycemia/hyperosmolality; overlap is common. Assess dehydration, Kussmaul breathing, ketones/gap, osmolality, mentation, and precipitant.','Use local fluid/insulin/electrolyte pathway; check potassium before/during insulin; trend glucose, ketones/gap, bicarbonate/pH, sodium, potassium, phosphate, creatinine, osmolality, UOP, and mentation; add dextrose when ordered so insulin continues until crisis resolves.','Unsafe potassium, arrhythmia, shock, mentation decline, cerebral-edema concern, rapid sodium/osmolality shift, hypoglycemia, or overload are red flags. Glucose corrects before metabolic crisis. Source: 2024 hyperglycemic-crises consensus.');
updateDx('GI bleeding','GI bleeding ranges from occult to exsanguinating; early Hgb may appear normal. Assess emesis/stool, orthostasis, shock, BUN/creatinine, liver disease, varices, ulcer/NSAID/anticoagulant history, and procedures.','Establish access; send CBC/coags/type-and-screen/ordered chemistries; activate hemorrhage/transfusion pathways when indicated; give ordered resuscitation, PPI, vasoactive/antibiotic/reversal therapy; trend bleeding, Hgb, perfusion, UOP, calcium/coags; prepare source control.','Bright-red bleeding, shock, rapid transfusion, lactate, ischemia, coagulopathy, airway contamination, or suspected varices are red flags. Unstable hematochezia can be brisk upper-GI bleeding. Source: ACG upper-GI bleed guideline.');
updateDx('DIC','Systemic dysregulated coagulation from illness such as sepsis, trauma, malignancy, obstetric catastrophe, or tissue injury; thrombosis and bleeding can coexist. Assess oozing/bruising/ischemia, platelets, fibrin markers, PT/aPTT, fibrinogen, and serial trends.','Treat trigger urgently; trend platelets, PT/INR, aPTT, fibrinogen, D-dimer, Hgb, perfusion, bleeding, and thrombosis; minimize punctures; give components/anticoagulation only for specific indication under active plan.','Major bleeding, intracranial/pulmonary bleed concern, falling fibrinogen/platelets, ischemia, organ failure, or shock are red flags. A single nondiagnostic panel does not exclude evolving DIC. Source: British Society for Haematology DIC guideline.');
updateDx('Status epilepticus','Prolonged/recurrent seizure without recovery; ongoing electrical seizure can persist after convulsions stop. Assess exact onset, recurrent motor/subtle signs, baseline recovery, glucose, hypoxia, fever, electrolytes, adherence, intoxication/withdrawal, and CNS injury.','Document seizure/medication times; protect from injury; support ABCs; check glucose; give first/second-line therapy exactly per protocol; obtain ordered labs/imaging; use EEG when recovery is delayed or nonconvulsive seizure suspected; monitor respiratory/hemodynamic effects.','Persistent/recurrent seizure, apnea, hypoxemia, hypotension, hyperthermia, acidosis, pregnancy, trauma, or ongoing coma are red flags. Convulsions stopping is not proof status ended. Source: adult status-epilepticus guidance.');
updateDx('Increased ICP','ICP rises when brain tissue/blood/CSF expansion exhausts reserve, reducing CPP and risking herniation. Assess consciousness, agitation, vomiting, pupils, weakness/posturing, seizures, imaging, Cushing physiology, and confounders.','Escalate acute neuro change; elevate head/keep neck midline if appropriate; prevent hypoxemia, fever, hypotension, pain/agitation/coughing; trend pupils/exam, MAP, ICP/CPP, sodium/osmolality, renal function, and balance; give ordered hyperosmolar therapy and coordinate imaging/surgery.','Fixed/dilated pupil, rapid GCS decline, posturing, seizure, Cushing triad, ICP spike, or loss of reflexes are red flags. Avoid routine prolonged hyperventilation. Source: Neurocritical Care Society cerebral-edema guideline.');
updateDx('Post-cardiac arrest syndrome','After ROSC, ischemia-reperfusion can cause brain injury, myocardial dysfunction, inflammation, vasoplegia, and recurrent trigger; early neuro findings are often confounded. Assess hypotension, rhythm/ischemia, ventricular dysfunction, O2/CO2, seizures, temperature, glucose, lactate, and organ injury.','Follow post-ROSC pathway; secure oxygenation/ventilation while avoiding unnecessary hyperoxia; target ordered PaCO2/BP; treat cause; use temperature/febrile control; trend ECG/rhythm, hemodynamics, lactate, glucose/electrolytes, UOP, neuro exam, and EEG when indicated.','Re-arrest, dysrhythmia, shock, severe hypoxemia, extreme PaCO2, seizure, fever, lactate, or organ failure are red flags. Prevent secondary brain injury and delay prognostication until confounders/timing addressed. Source: 2025 AHA post-arrest guideline.');
updateDx('Hyperkalemia','Severe K elevation can cause fatal dysrhythmias even with an initially normal ECG. Confirm result/hemolysis when safe, but do not delay treatment for severe elevation or instability; obtain continuous monitoring, 12-lead ECG, repeat K, and assess renal function, acid-base status, glucose, contributors, tissue injury, and dialysis history.','IV calcium stabilizes myocardium with ECG change/instability but does not lower K. Shift K with insulin/dextrose and albuterol per order; consider bicarbonate with significant acidosis; remove K with appropriate diuresis, binder, or dialysis. Recheck K and glucose for rebound/delayed hypoglycemia.','ECG changes, K >6.5, rapid rise, weakness/paralysis, acidosis, oligo-anuria, tissue breakdown, or poor response are red flags. Use a membrane-stabilization, shift, and removal checklist. Source: ACEP adult hyperkalemia algorithm.');
updateDx('Hyponatremia','Risk depends on symptoms, sodium, and onset. Assess headache, nausea, confusion, seizure, coma, respiratory compromise, acute/chronic/unknown duration, glucose/osmolality, volume status, urine studies, medications, and endocrine/renal causes.','For severe neurologic symptoms, a common US regimen is 3% saline 100 mL IV over 10 min, repeat up to twice if symptoms persist; local orders control. Aim for a 4-6 mmol/L improvement-producing rise; check sodium/neuro status frequently and watch UOP for water diuresis.','Seizure, coma, worsening confusion, respiratory failure, water intoxication, or overcorrection are red flags. Avoid >8 mmol/L/24 hr correction in high-risk patients. Source: US/European guideline comparison.');
updateDx('Hypertensive emergency','Severe BP elevation plus new/worsening acute target-organ injury; the number alone is not the emergency. Confirm technique/cuff and assess brain, arteries, retina, kidneys, and heart.','Use monitored titratable IV therapy appropriate to the injured organ. Unless a diagnosis-specific pathway differs, lower SBP/MAP by no more than about 20-25% in the first hour, then toward roughly 160/100 over 2-6 hr if stable; reassess perfusion throughout.','Dissection, stroke/ICH, ACS/pulmonary edema, eclampsia, and catecholamine crisis need syndrome-specific target/drug/timeline. Treat organ injury, not monitor value. Source: AHA acute-care BP statement.');
updateDx('Alcohol withdrawal / CIWA-Ar','Withdrawal can progress from tremor/autonomic activation to seizures/DTs. CIWA-Ar is unreliable if intubated, deeply sedated, delirious, or noncommunicative. Assess last drink, intake, prior seizures/DTs, substances, vitals, orientation, tremor, hallucinations, glucose, electrolytes, and airway/ventilation.','Use local symptom-triggered, front-loading, or fixed-dose pathway; benzodiazepines are first-line. Use ICU RASS/MINDS approach if CIWA-Ar is invalid. Give ordered thiamine, correct deficits, use seizure/fall precautions, and reassess airway/cumulative sedation.','Seizure, DTs, unsafe agitation, autonomic instability, hyperthermia, rising sedative need, respiratory depression, or persistent delirium are red flags. Match scale to ability to participate. Source: ASAM alcohol withdrawal guideline.');
updateDx('Delirium / CAM-ICU','Acute fluctuating attention/cognition disturbance; hypoactive delirium is easily missed. RASS -4/-5 is coma and not CAM-ICU assessable. Assess CAM-ICU features, baseline cognition, oxygenation/ventilation, infection, pain, glucose, organ dysfunction, withdrawal, meds, retention, constipation, and sleep.','Trend RASS/CAM-ICU; treat driver and review deliriogenic medication. Apply ABCDEF bundle; promote sleep, daytime orientation, hydration, mobility, glasses/hearing aids, and family engagement when appropriate.','Focal deficit, seizure, falling consciousness, severe gas-exchange issue, hypoglycemia, sepsis, or unsafe agitation are red flags. A positive CAM-ICU identifies delirium, not its cause. Source: SCCM ICU Liberation Bundle.');
updateDx('ABG interpreter','Use a fixed sequence: pH, primary process, expected compensation, anion gap/albumin, mixed disorder, clinical cause. Review gas, chemistry HCO3 when available, Na/Cl/albumin, lactate/ketones. PaCO2 moves opposite pH in primary respiratory disease; HCO3 moves with pH in metabolic disease.','Metabolic acidosis expected PaCO2 = 1.5 x HCO3 + 8 +/-2; metabolic alkalosis expected PaCO2 about 0.7 x (HCO3-24)+40 +/-2. AG = Na-(Cl+HCO3); corrected AG about measured AG+2.5 x (4-albumin). Trend with ventilation/perfusion/treatment.','Compensation outside range, near-normal pH with abnormal PaCO2/HCO3, or high-gap mismatch suggests mixed disorder. Compensation does not normalize/overshoot pH. Source: Merck Manual acid-base disorders.');
updateDx('Oxygen-delivery devices','Delivered FiO2 is estimated unless fixed; fit, minute ventilation, mouth breathing, and equipment matter. Assess ordered SpO2 goal, O2 requirement, RR, work, mentation, oxygenation, and hypercapnia/acidosis.','NC 1-6 L/min about 24-44%; simple mask 6-10 L/min 35-50%, never <6; nonrebreather 10-15 L/min 60-80%, keep reservoir inflated; Venturi 24-60% adapter-specific; HFNC up to 60 L/min; CPAP one pressure, BiPAP IPAP/EPAP. Reassess after each change.','Rising O2 need, persistent hypoxemia, work, hypercapnia/acidosis, exhaustion, mentation decline, or no response are red flags. NIV may be unsafe with unprotected airway, vomiting, secretions, major instability, or poor interface. Source: Open RN oxygenation equipment.');
const updateMed=(name,overview,monitor,pearl,trim=false)=>{const x=meds.find(m=>m[0]===name);if(x){x[2]=overview;x[3]=monitor;x[4]=pearl;if(trim)x.splice(5)}};
updateMed('Norepinephrine','First-line catecholamine vasopressor for distributive shock; predominantly alpha-1 with some beta-1 activity. Label example: start 8-12 mcg/min and titrate; weight-based ranges are protocol-dependent. Premixes include 16, 32, or 64 mcg/mL.','Titrate to ordered MAP/perfusion target. Trend continuous BP, rhythm, cap refill, mentation, urine output, lactate, extremity temperature, and infusion site after every change. Verify concentration, access, and smart-pump guardrails.','Extravasation can cause necrosis: stop through the affected line and follow the local antidote pathway. Rising dose means reassess source control, volume, cardiac function, acidemia, and occult obstruction - not simply raise the pump. Source: FDA norepinephrine prescribing information.');
updateMed('Vasopressin','Non-catecholamine V1-mediated adjunct for vasodilatory shock despite fluids/catecholamines. Septic-shock label range: 0.01-0.07 units/min; many ICUs use fixed 0.03 units/min. Concentrations may be 0.1 or 1 unit/mL.','Follow the ordered fixed-dose or titration strategy. Trend MAP, perfusion, UOP, sodium, rhythm, cardiac output when available, and skin/digital/abdominal ischemic signs.','Escalate for bradycardia, falling cardiac output, hyponatremia, or coronary/mesenteric/skin/digital ischemia. Clarify the unit weaning strategy. Source: DailyMed vasopressin label.');
updateMed('Epinephrine','Alpha- and beta-adrenergic vasopressor/inotrope for refractory shock and indication-specific anaphylaxis/ACLS pathways. Septic-shock label range: 0.05-2 mcg/kg/min IV; emergency algorithms use different doses/routes. Premixes include 16 or 64 mcg/mL.','Use continuous BP/ECG. Trend perfusion, UOP, glucose, potassium, lactate, chest pain, and site; titrate to the ordered endpoint and wean gradually when stable.','Watch for hypertension, tachyarrhythmia, ischemia, pulmonary edema, hyperglycemia, hypokalemia, and extravasation. Epinephrine can raise lactate via beta-2 stimulation: interpret with whole-patient perfusion. Source: DailyMed epinephrine label.');
updateMed('Phenylephrine','Predominantly alpha-1 vasopressor that raises SVR with little direct beta activity. Common ICU range: 40-180 mcg/min IV; bolus and maximums are protocol-dependent. The 10 mg/mL vial requires dilution.','Titrate to ordered MAP/BP. Trend continuous BP, HR/rhythm, peripheral perfusion, UOP, cardiac output when available, and site.','Reduce/stop per order for severe bradycardia, falling cardiac output, hypertension, ischemia, or extravasation. BP improvement with worsening perfusion should prompt reassessment of stroke volume/cause. Source: DailyMed phenylephrine label.');
updateMed('Dobutamine','Primarily beta-1 inotrope for low-output states when contractility support is needed and BP can tolerate beta-2 vasodilation. Start low, commonly 0.5-1 mcg/kg/min; usual effective range about 2-20 mcg/kg/min. Do not mix with sodium bicarbonate.','Titrate to ordered cardiac-output/perfusion endpoint. Trend continuous ECG, HR, BP, UOP, lactate/perfusion, ectopy, and cardiac output/filling pressures when available.','Tachyarrhythmia, ectopy, ischemia, and hypotension may limit therapy. Correct hypovolemia when appropriate; faster HR without better perfusion is not success. Source: DailyMed dobutamine label.');
updateMed('Diltiazem','Non-dihydropyridine calcium-channel blocker for selected AF/flutter or SVT. Label bolus: 0.25 mg/kg IV over 2 min, then 0.35 mg/kg after 15 min if needed. Infusion commonly 5-10 mg/hr, up to 15 mg/hr for up to 24 hr.','Use continuous ECG/BP. Titrate to ordered ventricular-rate goal; trend rhythm, HR, BP, symptoms, perfusion, and worsening-HF signs.','Avoid/escalate with hypotension, cardiogenic shock, severe HFrEF/decompensated systolic failure, significant AV block without pacing, sick sinus, or AF with pre-excitation. Source: DailyMed diltiazem label.');
updateMed('Propofol','Rapid-onset sedative for intubated ventilated adults; provides no analgesia. Label start: 5 mcg/kg/min, increase 5-10 mcg/kg/min no faster than every 5 min; typical ICU maintenance 5-50 mcg/kg/min. Standard emulsion is 10 mg/mL, generally undiluted.','Titrate to RASS and ventilator synchrony. Continuously monitor BP/respiration; trend triglycerides, lipid calories, and CK/lactate/acid-base status when indicated. Follow aseptic, tubing, hang-time, and discard policy.','Watch for hypotension, apnea, hypertriglyceridemia, pancreatitis, and infection risk. Stop/escalate for possible propofol infusion syndrome: unexplained acidosis, rhabdomyolysis, hyperkalemia, bradyarrhythmia, cardiac failure, or renal injury. Source: DailyMed propofol label.');
updateMed('Dexmedetomidine','Alpha-2 sedative supporting lighter, arousable sedation with relatively little respiratory depression. Label maintenance: 0.2-0.7 mcg/kg/hr; a 1 mcg/kg load is often omitted by ICU protocols because of bradycardia/hypotension. Common ready-to-use concentration is 4 mcg/mL.','Titrate to ordered RASS/goal. Continuously monitor HR, BP, oxygenation, mental status, and comfort; consider hepatic reduction and withdrawal after prolonged exposure.','Bradycardia, sinus pauses, hypotension, and transient load-associated hypertension can occur. A calm/arousable patient may still need separate analgesia. Source: DailyMed dexmedetomidine label.');
updateMed('Fentanyl','Rapid-onset opioid for acute pain and analgesia-first sedation; it does not replace a separate sedation assessment. Common examples: 25-50 mcg IV bolus or 0.5-3 mcg/kg/hr infusion, protocol-dependent. Commercial injection is commonly 50 mcg/mL.','Titrate to ordered pain score/CPOT and ventilator goal. Monitor RR, SpO2, ventilation/ETCO2 when available, BP, HR, sedation, bowel function, urinary retention, and cumulative exposure.','Watch for respiratory depression, apnea, hypotension, bradycardia, ileus, and chest-wall rigidity after rapid/high-dose IV. Plan for accumulation, tolerance, and withdrawal with prolonged infusion. Source: DailyMed fentanyl label.');
updateMed('Midazolam','Benzodiazepine for selected procedures, seizures, and ICU sedation; provides no analgesia. If loading is ordered: 0.01-0.05 mg/kg IV slowly; common maintenance 0.02-0.1 mg/kg/hr. Continuous-infusion label dilution: 5 mg/mL product to 0.5 mg/mL in NS/D5W.','Titrate to ordered RASS/indication. Monitor BP, respiratory rate, SpO2/ventilation, mental status, and cumulative dose; reassess for awakening and continued need when appropriate.','Respiratory depression, apnea, hypotension, paradoxical agitation, and prolonged awakening can occur. Accumulation rises with long infusions, obesity, renal/hepatic dysfunction, and opioids. Source: DailyMed midazolam label.');
updateMed('Insulin','Regular-insulin infusion is used for DKA/HHS or critical-care hyperglycemia; separate hyperkalemia bolus protocols differ. DKA example: 0.1 units/kg/hr after fluids and potassium assessment. A common infusion is 100 units/100 mL NS (1 unit/mL).','Follow active protocol exactly. Check glucose at the ordered frequency, often hourly during titration; trend potassium, anion gap/beta-hydroxybutyrate, bicarbonate/pH, osmolality, and neurologic status as indicated.','Hypoglycemia/hypokalemia can be rapid or delayed. Do not stop DKA insulin solely because glucose normalizes if ketoacidosis persists. Continue glucose checks after hyperkalemia insulin. Source: 2024 hyperglycemic-crises consensus report.');
updateMed('Sodium bicarbonate','Alkalinizing agent for selected severe acidosis, hyperkalemia with acidosis, sodium-channel blocker toxicity, and indication-specific protocols; it generates CO2 and does not correct the cause. Hyperkalemia/acidosis example: 50 mEq IV over 5-15 min. 8.4% = 1 mEq/mL; 4.2% = 0.5 mEq/mL.','Reassess pH/PaCO2, bicarbonate, sodium, potassium, ionized calcium, volume, ECG, and ventilation after each dose. In toxicity, use ordered ECG/pH endpoints rather than empiric repeat dosing.','Watch for hypernatremia, alkalemia, hypokalemia, reduced ionized calcium, volume overload, extravasation, and intracellular acidosis if ventilation cannot clear CO2. Do not mix with incompatible calcium/catecholamine solutions. Source: DailyMed sodium bicarbonate label.');
updateMed('Rocuronium / succinylcholine','RSI neuromuscular blockers: neither provides sedation, amnesia, or analgesia. Rocuronium 0.6-1.2 mg/kg IV; succinylcholine average label dose 0.6 mg/kg IV, with many RSI protocols using 1-1.5 mg/kg. Common vial concentrations: rocuronium 10 mg/mL and succinylcholine 20 mg/mL.','A single RSI dose is not titrated. Confirm induction, airway/ventilation readiness, and post-intubation analgesia/sedation plan. Use TOF/local pathway for ongoing blockade.','Maintain immediate oxygenation/ventilation capability. Avoid succinylcholine after acute burns, crush injury, denervation, UMN injury, or myopathy; assess malignant-hyperthermia, bradycardia, and prolonged-apnea risk. Paralysis can hide pain/seizures. Source: DailyMed rocuronium and succinylcholine labels.',true);
updateMed('Nicardipine','Titrated arterial vasodilator for short-term severe hypertension when oral therapy is not feasible. Start 5 mg/hr; increase 2.5 mg/hr every 5 min (rapid) or 15 min (gradual); max 15 mg/hr. Premixes include 0.1 and 0.2 mg/mL.','Continuously monitor BP/HR; titrate to ordered SBP/MAP and reassess neurologic, cardiac, renal, and peripheral perfusion. Use large peripheral or central access and inspect site per policy.','Avoid precipitous lowering. Reduce/stop for unacceptable hypotension/tachycardia; watch for site injury, angina/HF worsening. Contraindicated in advanced aortic stenosis. Source: DailyMed Cardene IV label.',true);
updateMed('Nitroglycerin','Venodilator with dose-dependent arterial effects for acute ischemia, cardiogenic pulmonary edema, and selected hypertension when preload/BP permit. Start 5 mcg/min; raise 5 mcg/min every 3-5 min initially, then ordered 10-20 mcg/min steps if needed. Premixes include 100-400 mcg/mL.','Continuously monitor BP/HR. Titrate to ordered BP and relief of chest pain, work of breathing, or pulmonary edema; reassess perfusion/hemodynamics after changes. Use non-adsorptive tubing and product-specific filter policy.','Reduce/stop for hypotension, syncope, worsening ischemia, or marked rate change. Avoid with recent PDE-5 inhibitor/riociguat exposure and preload-dependent states such as RV infarct/tamponade. Source: DailyMed nitroglycerin IV label.',true);
updateMed('Furosemide infusion','Continuous loop diuretic for pulmonary edema/severe overload when controlled diuresis is desired. A common adult approach is a loading dose then 5-20 mg/hr, individualized to renal function, prior dose, and response; do not exceed 4 mg/min IV. Common concentration: 1 mg/mL.','Titrate to ordered UOP, net balance, weight, symptoms, or filling pressure. Track strict I/O, hourly UOP, weight, BP, creatinine/BUN, Na/K/Mg/bicarbonate, and hearing symptoms.','Contraindicated in anuria. Stop/escalate for hypotension, worsening oliguria/azotemia, symptomatic electrolyte loss, or hearing change. Reassess perfusion, obstruction, adequacy, and resistance before simple escalation. Source: DailyMed furosemide label.',true);
updateMed('Magnesium sulfate','IV magnesium treats hypomagnesemia and torsades/polymorphic VT with prolonged QT. Torsades-with-pulse example: 1-2 g IV diluted over about 5-15 min; replacement thresholds/rates are protocol-dependent. Common premixes: 1 g/100 mL, 2 g/50 mL, 4 g/100 mL.','Recheck magnesium per protocol; trend potassium, calcium, renal function/UOP, BP, respiratory status, and reflexes. Use ECG monitoring for unstable arrhythmia or rapid administration.','Reduce repeated empiric dosing in renal impairment. Stop/escalate for hyporeflexia, weakness, respiratory depression, hypotension/bradycardia, heart block, or worsening conduction. Verify grams vs milligrams/concentration. Source: electrolyte-replacement protocols.',true);
const $=s=>document.querySelector(s), app=$('#app');let tab='home',query='',detail=null;let fav=JSON.parse(localStorage.favs||'[]');const esc=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
function header(){return `<header class="top"><div class="brand"><div class="mark">+</div><div><div class="eyebrow">Personal bedside brain</div><div class="title">ICU Pocket Reference</div></div></div><button class="back" onclick="show('favorites')">★ ${fav.length}</button></header>`}function cards(){return `<div class="grid"><button class="card" onclick="show('meds')"><div class="icon">💊</div><strong>Medications</strong><small>${meds.length} quick cards</small></button><button class="card" onclick="show('dx')"><div class="icon">▣</div><strong>Conditions</strong><small>${dx.length} ICU essentials</small></button><button class="card" onclick="show('quick')"><div class="icon">⚡</div><strong>Right now</strong><small>Problem guides</small></button><button class="card" onclick="show('calcs')"><div class="icon">⌁</div><strong>Calculators</strong><small>7 bedside tools</small></button><button class="card" onclick="show('notes')"><div class="icon">✎</div><strong>My protocols</strong><small>Private local notes</small></button></div>`}
function list(items,type){let filtered=items.filter(x=>x.join(' ').toLowerCase().includes(query.toLowerCase()));return `<h2>${type==='med'?'Medications':'Conditions'}</h2><div class="count">${filtered.length} result${filtered.length===1?'':'s'}</div><div class="list">${filtered.map((x,i)=>`<button class="item" onclick="openDetail('${type}',${items.indexOf(x)})"><span class="tag">${esc(x[1])}</span><h3>${esc(x[0])}</h3><small>${esc(x[2])}</small>${fav.includes(type+items.indexOf(x))?'<span class="star">★</span>':''}</button>`).join('')||'<div class="empty">No matching reference found.</div>'}</div>`}
function detailView(type,i){let x=(type==='med'?meds:dx)[i],id=type+i,star=fav.includes(id),detail=x[5]?`<div class="section"><h3>Batch 2 bedside card</h3><p>${esc(x[5]).replace(/\n/g,'<br>')}</p>${x[6]?`<small>Source: ${esc(x[6])}</small>`:''}</div>`:'';return `<button class="back" onclick="show('${type==='med'?'meds':'dx'}')">← Back</button><article class="detail"><div class="detail-head"><div><h1>${esc(x[0])}</h1><div class="tag">${esc(x[1])} · general education</div></div><button class="star" onclick="toggleFav('${id}')">${star?'★':'☆'}</button></div><div class="section"><h3>Overview</h3><p>${esc(x[2])}</p></div><div class="section"><h3>Monitor / trend</h3><p>${esc(x[3])}</p></div><div class="section warn"><h3>ICU pearl</h3><p>${esc(x[4])}</p></div>${detail}${noteBox(id,x[0])}</article>`}
function noteBox(id,name){return `<div class="protocol"><label>MY WORKPLACE NOTES — PRIVATE / LOCAL ONLY</label><small>Not a hospital policy. Verify against your current orders, policies, and pharmacy guidance.</small><textarea id="note">${esc(localStorage['note-'+id]||'')}</textarea><button class="save" onclick="saveNote('${id}')">Save notes for ${esc(name)}</button></div>`}
function quickView(){return `<h2>Right now</h2><p class="count">General reference only — use emergency response systems and local protocols.</p><div class="list">${quick.map((x,i)=>`<button class="item" onclick="openDetail('quick',${i})"><span class="tag">Problem guide</span><h3>${x[0]}</h3><small>${x[1]}</small></button>`).join('')}</div>`}function quickDetail(i){let x=quick[i];return `<button class="back" onclick="show('quick')">← Back</button><article class="detail"><h1>${x[0]}</h1><div class="section danger"><h3>Rapid bedside check</h3><p>${x[1]}</p></div><div class="section warn"><h3>Communicate / escalate</h3><p>${x[2]}</p></div>${noteBox('quick'+i,x[0])}</article>`}
const calc=[['MAP','(SBP + 2 × DBP) ÷ 3',[['SBP','sbp'],['DBP','dbp']],v=>((v.sbp+2*v.dbp)/3).toFixed(0)+' mmHg'],['Anion gap','Na − (Cl + HCO₃)',[['Na','na'],['Cl','cl'],['HCO₃','hco3']],v=>(v.na-v.cl-v.hco3).toFixed(1)+' mEq/L'],['Corrected sodium','Na + 1.6 × ((glucose − 100) ÷ 100)',[['Na','na'],['Glucose','glu']],v=>(v.na+1.6*((v.glu-100)/100)).toFixed(1)+' mEq/L'],['Corrected calcium','Ca + 0.8 × (4 − albumin)',[['Calcium','ca'],['Albumin','alb']],v=>(v.ca+.8*(4-v.alb)).toFixed(2)+' mg/dL'],['P/F ratio','PaO₂ ÷ FiO₂ (decimal)',[['PaO₂','pao2'],['FiO₂ %','fio2']],v=>(v.pao2/(v.fio2/100)).toFixed(0)],['QTc (Bazett)','QT ÷ √RR (both in seconds)',[['QT ms','qt'],['HR bpm','hr']],v=>{let rr=60/v.hr;return (v.qt/1000/Math.sqrt(rr)*1000).toFixed(0)+' ms'}],['Shock index','HR ÷ SBP',[['HR','hr'],['SBP','sbp']],v=>(v.hr/v.sbp).toFixed(2)]];
function calcs(){return `<h2>Calculators</h2><p class="count">Check units and interpret with the full clinical picture.</p>${calc.map((c,i)=>`<div class="calc"><h3>${c[0]}</h3><small>${c[1]}</small><div class="fields">${c[2].map(f=>`<label>${f[0]}<input type="number" inputmode="decimal" id="c${i}-${f[1]}" oninput="runCalc(${i})"></label>`).join('')}</div><div class="result" id="r${i}">—</div></div>`).join('')}`}
function notes(){return `<h2>My protocols & notes</h2><div class="protocol"><label>PRIVATE WORKPLACE REFERENCE</label><p>Keep hospital-specific policies, phone numbers, dilution notes, and workflow reminders here. This stays in this browser on this device.</p><textarea id="master-note" placeholder="Example: Sepsis pathway location, rapid response extension, unit-specific titration reminder…">${esc(localStorage.masterNotes||'')}</textarea><button class="save" onclick="localStorage.masterNotes=$('#master-note').value;alert('Saved on this device.')">Save my notes</button></div><div class="section warn"><h3>Safety boundary</h3><p>This app is a personal educational reference, not a prescribing tool or replacement for clinical judgment, orders, current institutional policy, pharmacy guidance, or emergency response procedures.</p></div>`}
function render(){let body=detail?(detail.type==='quick'?quickDetail(detail.i):detailView(detail.type,detail.i)):tab==='home'?`<div class="disclaimer"><strong>General education only.</strong> Use current orders, institution policies, pharmacy guidance, and clinical judgment.</div><div class="search">⌕ <input autofocus placeholder="Search meds, conditions, problems…" value="${esc(query)}" oninput="query=this.value;searchAll()"></div>${query?searchResults():`<h2>Quick access</h2><div class="quick">${quick.slice(0,3).map((x,i)=>`<button class="card" onclick="openDetail('quick',${i})"><div class="tag">Right now</div><strong>${x[0]}</strong></button>`).join('')}</div><h2>Browse</h2>${cards()}`}`:tab==='meds'?list(meds,'med'):tab==='dx'?list(dx,'dx'):tab==='quick'?quickView():tab==='calcs'?calcs():tab==='notes'?notes():favorites();app.innerHTML=header()+body+`<nav class="nav"><div class="nav-inner">${[['home','⌂','Home'],['meds','💊','Meds'],['dx','▣','Conditions'],['calcs','⌁','Tools'],['notes','✎','Notes']].map(n=>`<button class="${tab===n[0]&&!detail?'active':''}" onclick="show('${n[0]}')"><span>${n[1]}</span>${n[2]}</button>`).join('')}</div></nav>`}
function searchResults(){let all=[...meds.map((x,i)=>['med',i,x]),...dx.map((x,i)=>['dx',i,x]),...quick.map((x,i)=>['quick',i,x])].filter(x=>x[2].join(' ').toLowerCase().includes(query.toLowerCase()));return `<h2>Search</h2><div class="list">${all.map(x=>`<button class="item" onclick="openDetail('${x[0]}',${x[1]})"><span class="tag">${x[0]==='med'?'Medication':x[0]==='dx'?'Condition':'Problem guide'}</span><h3>${x[2][0]}</h3><small>${x[2][2]}</small></button>`).join('')||'<div class="empty">No matches.</div>'}</div>`}function favorites(){let all=[...meds.map((x,i)=>['med',i,x]),...dx.map((x,i)=>['dx',i,x])].filter(x=>fav.includes(x[0]+x[1]));return `<h2>Favorites</h2><div class="list">${all.map(x=>`<button class="item" onclick="openDetail('${x[0]}',${x[1]})"><span class="tag">${x[2][1]}</span><h3>${x[2][0]}</h3></button>`).join('')||'<div class="empty">Tap ☆ on any medication or condition to keep it here.</div>'}</div>`}function show(x){tab=x;detail=null;query='';render();scrollTo(0,0)}function openDetail(type,i){detail={type,i};render();scrollTo(0,0)}function toggleFav(id){fav=fav.includes(id)?fav.filter(x=>x!==id):[...fav,id];localStorage.favs=JSON.stringify(fav);render()}function saveNote(id){localStorage['note-'+id]=$('#note').value;alert('Saved on this device.')}function runCalc(i){let c=calc[i],v={};c[2].forEach(f=>v[f[1]]=Number($('#c'+i+'-'+f[1]).value));$('#r'+i).textContent=c[2].every(f=>Number.isFinite(v[f[1]])&&v[f[1]]!==0)?c[3](v):'—'}function searchAll(){render()}if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');render();
const refs=[
['Sepsis & septic shock','Surviving Sepsis Campaign, 2021','https://www.idsociety.org/practice-guideline/surviving-sepsis-campaign-adult-guidelines-2021','Primary guideline for septic-shock content and vasopressor framing.'],
['Cardiac arrest / post-ROSC','American Heart Association: Adult Advanced Life Support','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-advanced-life-support/','Current AHA guideline hub for adult cardiac arrest and cardiovascular emergencies.'],
['Sedation, analgesia & delirium','SCCM PADIS Guidelines','https://www.sccm.org/clinical-resources/guidelines/guidelines/guidelines-for-the-prevention-and-management-of-pa','Source for general ICU sedation and analgesia concepts.'],
['Acute kidney injury','KDIGO AKI / AKD Guideline hub','https://kdigo.org/guidelines/acute-kidney-injury/','Check current publication status and your local pathway.'],
['Medication details','FDA Drugs@FDA','https://www.accessdata.fda.gov/scripts/cder/daf/','Use current labeling, pharmacy guidance, and local policy for doses and administration.']];
function references(){return `<h2>References</h2><p class="count">Starter sources for this educational build. Check the current guideline and follow local policy where it differs.</p><div class="list">${refs.map(r=>`<a class="item" style="color:var(--text);text-decoration:none" href="${r[2]}" target="_blank" rel="noopener"><span class="tag">${r[0]}</span><h3>${r[1]} ↗</h3><small>${r[3]}</small></a>`).join('')}</div><div class="section warn"><h3>Source scope</h3><p>These sources support the general topics; bedside summaries are not line-by-line evidence mapped. Medication doses, dilutions, compatibility, and titration are intentionally omitted: use your pharmacy and institutional references.</p></div>`}
cards=()=>`<div class="grid"><button class="card" onclick="show('meds')"><div class="icon">M</div><strong>Medications</strong><small>${meds.length} quick cards</small></button><button class="card" onclick="show('dx')"><div class="icon">+</div><strong>Conditions</strong><small>${dx.length} ICU essentials</small></button><button class="card" onclick="show('quick')"><div class="icon">!</div><strong>Right now</strong><small>Problem guides</small></button><button class="card" onclick="show('calcs')"><div class="icon">#</div><strong>Calculators</strong><small>7 bedside tools</small></button><button class="card" onclick="show('notes')"><div class="icon">N</div><strong>My protocols</strong><small>Private local notes</small></button><button class="card" onclick="show('refs')"><div class="icon">R</div><strong>References</strong><small>Guidelines & sources</small></button></div>`;
render=function(){let body=detail?(detail.type==='quick'?quickDetail(detail.i):detailView(detail.type,detail.i)):tab==='home'?`<div class="disclaimer"><strong>General education only.</strong> Use current orders, institution policies, pharmacy guidance, and clinical judgment.</div><div class="search">Search <input autofocus placeholder="Search meds, conditions, problems..." value="${esc(query)}" oninput="query=this.value;searchAll()"></div>${query?searchResults():`<h2>Quick access</h2><div class="quick">${quick.slice(0,3).map((x,i)=>`<button class="card" onclick="openDetail('quick',${i})"><div class="tag">Right now</div><strong>${x[0]}</strong></button>`).join('')}</div><h2>Browse</h2>${cards()}`}`:tab==='meds'?list(meds,'med'):tab==='dx'?list(dx,'dx'):tab==='quick'?quickView():tab==='calcs'?calcs():tab==='notes'?notes():tab==='refs'?references():favorites();app.innerHTML=header()+body+`<nav class="nav"><div class="nav-inner">${[['home','Home'],['meds','Meds'],['dx','Conditions'],['calcs','Tools'],['notes','Notes']].map(n=>`<button class="${tab===n[0]&&!detail?'active':''}" onclick="show('${n[0]}')">${n[1]}</button>`).join('')}</div></nav>`};render();
